// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Run one command: status, log, ledger, caps, pause, unlock, login, run, ask
// Flo: command word > state-only commands first > browser commands (login, run, ask) > print result
// I/O: Ctx + Args (caller) > text or JSON lines on stdout (sink in tests), exit code 0 on success
// ===================================================================
const std = @import("std"); const task = @import("ru-task-runn.zig"); const targ = @import("ct-ctrl-args.zig"); const pace = @import("ru-huma-pace.zig"); const halt = @import("ru-safe-halt.zig"); const post = @import("ru-post-main.zig"); const repl = @import("ru-feed-repl.zig"); const dmsg = @import("ru-dmsg-main.zig"); const mark = @import("ru-mark-list.zig"); const reci = @import("ru-reci-main.zig"); const smar = @import("ru-smar-adap.zig");
const KINDS = [_]pace.Kind{ .post, .comm, .mark, .grou, .frie, .dmsg, .reac, .shar, .admn, .evnt, .stor, .prof };
const CF = .{ .dayz = 86400000, .nlog = 20, .poll = 2000, .minz = 10 };
pub const BROW = [_][]const u8{ "login", "run", "ask" };
pub fn needBrow(cmdz: []const u8) bool { for (BROW) |nam| if (std.mem.eql(u8, nam, cmdz)) return true; return false; }
const CapRow = struct { kind: []const u8, used: i64, cap: u32 };
const Stz = struct { app: []const u8, paused: bool, warm_perc: u32, quiet_now: bool, last_halt: []const u8, caps: []const CapRow };
fn capRows(ctx: *task.Ctx) ![]const CapRow { const now = task.nowMs(ctx); const born = try ctx.store.bornGet(now); const perc = pace.warmPerc(born, now, ctx.conf.warm_dayz_coun); var out: std.ArrayList(CapRow) = .empty; for (KINDS) |kin| try out.append(ctx.aren, .{ .kind = @tagName(kin), .used = try ctx.store.actCnt(@tagName(kin), now - CF.dayz), .cap = pace.capEff(pace.capOf(ctx.conf, kin), perc) }); return out.items; }
fn lastHalt(ctx: *task.Ctx) ![]const u8 { const rows = try ctx.store.logRecent(ctx.aren, 200); for (rows) |row| { if (std.mem.eql(u8, row.kind, "halt")) return row.what; } return ""; }
fn statusRun(ctx: *task.Ctx, args: targ.Args) !void { const now = task.nowMs(ctx); const born = try ctx.store.bornGet(now); const stz: Stz = .{ .app = "fb", .paused = try ctx.store.flagGet("pause"), .warm_perc = pace.warmPerc(born, now, ctx.conf.warm_dayz_coun), .quiet_now = pace.quietNow(now, ctx.conf.quie_zone_minu, ctx.conf.quie_hour_rang), .last_halt = try lastHalt(ctx), .caps = try capRows(ctx) }; if (args.json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, stz, .{})}); return; } task.say(ctx, "fb status: paused={any} warm-up={d}% quiet-now={any} last-halt={s}", .{ stz.paused, stz.warm_perc, stz.quiet_now, if (stz.last_halt.len > 0) stz.last_halt else "none" }); for (stz.caps) |row| task.say(ctx, "  {s}: {d}/{d} in the last 24h", .{ row.kind, row.used, row.cap }); }
fn ledgerRun(ctx: *task.Ctx, args: targ.Args) !void { const rows = try ctx.store.ledgList(ctx.aren); if (args.json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, rows, .{})}); return; } if (rows.len == 0) { task.say(ctx, "ledger is empty", .{}); return; } for (rows) |row| task.say(ctx, "#{d} [{s}] \"{s}\" group=\"{s}\" posted={d} updated={d} id={s}", .{ row.id, row.st, row.titl, row.grou, row.pms, row.ums, row.lid }); }
fn logRun(ctx: *task.Ctx, args: targ.Args) !void { const rows = try ctx.store.logRecent(ctx.aren, CF.nlog); if (args.json) { task.say(ctx, "{s}", .{try std.json.Stringify.valueAlloc(ctx.aren, rows, .{})}); return; } if (rows.len == 0) { task.say(ctx, "log is empty", .{}); return; } for (rows) |row| task.say(ctx, "{d} {s} {s} {s}", .{ row.ts, if (row.ok) "ok  " else "FAIL", row.kind, row.what }); }
fn loginRun(ctx: *task.Ctx) !void { ctx.page.arm(ctx.conf.brow_time_seco * 1000); try ctx.page.navigate(ctx.aren, ctx.base); task.say(ctx, "log in to Facebook in the browser window (QR/2FA by hand). Waiting...", .{}); const tot = @as(u64, ctx.conf.brow_time_seco) * 5000; var wtd: u64 = 0; while (wtd <= tot) { ctx.page.arm(ctx.conf.brow_time_seco * 1000); const urlz = ctx.page.urlNow(ctx.aren) catch ""; const txt = ctx.page.textNow(ctx.aren) catch ""; if (txt.len >= CF.minz and halt.check(urlz, txt, "") == null) { task.say(ctx, "logged in", .{}); return; } pace.nap(ctx.iozz, CF.poll, ctx.conf.time_scal_perc); wtd += CF.poll; } return error.Timeout; }
fn jobRun(ctx: *task.Ctx, job: []const u8, tsk: task.Args) !void { if (std.mem.eql(u8, job, "post")) { _ = try post.postRun(ctx, tsk); } else if (std.mem.eql(u8, job, "page")) { _ = try dmsg.pageRun(ctx, tsk); } else if (std.mem.eql(u8, job, "dm")) { _ = try dmsg.dmRun(ctx, tsk); } else if (std.mem.eql(u8, job, "join")) { _ = try dmsg.joinRun(ctx, tsk); } else if (std.mem.eql(u8, job, "friend")) { _ = try dmsg.friendRun(ctx, tsk); } else if (std.mem.eql(u8, job, "reply")) { const cnt = try repl.replRun(ctx, tsk); task.say(ctx, "replies handled: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "list")) { _ = try mark.listRun(ctx, tsk); } else if (std.mem.eql(u8, job, "renew")) { _ = try mark.renewRun(ctx, tsk); } else if (std.mem.eql(u8, job, "renewall")) { const cnt = try mark.renewAll(ctx, tsk); task.say(ctx, "listings renewed: {d}", .{cnt}); } else if (std.mem.eql(u8, job, "sold")) { _ = try mark.soldRun(ctx, tsk); } else return error.NoJob; }
fn askRun(ctx: *task.Ctx, text: []const u8, base: task.Args) !void { const cmd = (try reci.parse(ctx.aren, text)) orelse { task.say(ctx, "I did not understand. Try: post: <text> | reply to my comments | renew my listings | mark <title> sold | message <id> <text>", .{}); return error.BadUsage; }; var tsk = cmd.args; tsk.maxn = base.maxn; task.say(ctx, "understood: {s}", .{@tagName(cmd.job)}); try jobRun(ctx, @tagName(cmd.job), tsk); }
pub fn dispatch(ctx: *task.Ctx, args: targ.Args) !u8 { const cmd = args.cmdz; if (ctx.conf.smar_mode_enab and ctx.draft == null) ctx.draft = smar.draftChain; if (std.mem.eql(u8, cmd, "status") or std.mem.eql(u8, cmd, "caps")) { try statusRun(ctx, args); } else if (std.mem.eql(u8, cmd, "ledger")) { try ledgerRun(ctx, args); } else if (std.mem.eql(u8, cmd, "log")) { try logRun(ctx, args); } else if (std.mem.eql(u8, cmd, "pause")) { try ctx.store.flagSet("pause", true); task.say(ctx, "paused: running jobs stop at the next step", .{}); } else if (std.mem.eql(u8, cmd, "resume")) { try ctx.store.flagSet("pause", false); task.say(ctx, "resumed", .{}); } else if (std.mem.eql(u8, cmd, "unlock")) { if (args.subz.len == 0) return error.BadUsage; try ctx.store.keyDrop(args.subz); task.say(ctx, "unlocked: {s}", .{args.subz}); } else if (std.mem.eql(u8, cmd, "login")) { try loginRun(ctx); } else if (std.mem.eql(u8, cmd, "run")) { if (args.subz.len == 0) return error.BadUsage; try jobRun(ctx, args.subz, args.tsk); } else if (std.mem.eql(u8, cmd, "ask")) { if (args.subz.len == 0) return error.BadUsage; try askRun(ctx, args.subz, args.tsk); } else return error.BadUsage; return 0; }
